import type { ColumnType } from './ir.js';
export type TsTypeOf<T extends ColumnType> = {
    text: string;
    uuid: string;
    integer: number;
    bigint: number;
    boolean: boolean;
    jsonb: unknown;
    timestamp: string;
}[T];
export interface BaseRow {
    id: string;
    createdAt: string;
    updatedAt: string;
}
export type InferRow = BaseRow & Record<string, unknown>;
export type InferSchema = {
    tables: Record<string, InferRow>;
    resourceTables: Record<string, InferRow>;
};
